head.b:skin:
:root {
  --bg: #f7f4ec;
  --surface: #fffdf8;
  --surface-2: #efe9db;
  --ink: #22301f;
  --ink-soft: #5a6653;
  --line: #ddd5c2;
  --green: #1e5c38;
  --green-dark: #14402a;
  --green-soft: #e3efe2;
  --red: #b23a1f;
  --red-dark: #93300f;
  --amber: #e8a020;
  --wa: #1faa55;
  --wa-dark: #157a3c;
  --shadow: 0 10px 30px rgba(34, 48, 31, .14);
  --radius: 14px;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #141a13;
    --surface: #1e261d;
    --surface-2: #28311f;
    --ink: #eef2e6;
    --ink-soft: #a9b6a0;
    --line: #39442f;
    --green: #3f9e63;
    --green-dark: #2c7a49;
    --green-soft: #24382a;
    --red: #e0684a;
    --red-dark: #c8502f;
    --amber: #f0b23e;
    --wa: #25c05e;
    --wa-dark: #1faa55;
    --shadow: 0 10px 30px rgba(0, 0, 0, .45);
  }
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  font-family: "Archivo", system-ui, sans-serif;
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}
button, input, select, textarea { font: inherit; }
button { cursor: pointer; }
img { display: block; max-width: 100%; }

/* ---------- Header ---------- */
header.topbar {
  position: sticky; top: 0; z-index: 40;
  background: var(--green-dark);
  color: #fff;
  box-shadow: 0 2px 14px rgba(0,0,0,.25);
}
.topbar-in {
  max-width: 1120px; margin: 0 auto;
  display: flex; align-items: center; gap: 12px;
  padding: 10px 16px;
}
.brand { display: flex; align-items: baseline; gap: 10px; min-width: 0; }
.brand h1 {
  font-family: "Bitter", serif; font-weight: 800;
  font-size: clamp(26px, 5vw, 34px); line-height: 1; margin: 0;
  letter-spacing: .2px; white-space: nowrap;
}
.brand h1 .accent { color: var(--amber); }
.brand small {
  font-size: 12.5px; font-weight: 600; opacity: .85;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
@media (max-width: 560px) { .brand small { display: none; } }
.cart-btn {
  margin-left: auto; flex: none;
  display: inline-flex; align-items: center; gap: 9px;
  background: var(--amber); color: #2a1c05; border: 0;
  font-weight: 800; font-size: 15px;
  padding: 10px 16px; border-radius: 999px; min-height: 44px;
}
.cart-btn:active { transform: scale(.97); }
.cart-count {
  background: var(--red); color: #fff; border-radius: 999px;
  min-width: 24px; height: 24px; padding: 0 6px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 13px; font-weight: 800;
}

/* ---------- Hero ---------- */
.hero { position: relative; max-height: 340px; overflow: hidden; }
.hero img { width: 100%; height: 340px; object-fit: cover; }
.hero-veil {
  position: absolute; inset: 0;
  background: linear-gradient(90deg, rgba(16, 34, 20, .82) 0%, rgba(16, 34, 20, .55) 55%, rgba(16, 34, 20, .12) 100%);
  display: flex; align-items: center;
}
.hero-text { max-width: 1120px; margin: 0 auto; padding: 24px 16px; width: 100%; color: #fff; }
.hero-text h2 {
  font-family: "Bitter", serif; font-weight: 800;
  font-size: clamp(28px, 6vw, 44px); line-height: 1.08; margin: 0 0 10px;
  max-width: 560px;
}
.hero-text p { margin: 0 0 16px; font-size: clamp(15px, 2.6vw, 17px); max-width: 480px; opacity: .94; }
.hero-badges { display: flex; flex-wrap: wrap; gap: 8px; }
.hero-badges span {
  background: rgba(255,255,255,.14); border: 1px solid rgba(255,255,255,.35);
  padding: 6px 12px; border-radius: 999px; font-size: 13px; font-weight: 600;
  backdrop-filter: blur(2px);
}

/* ---------- Search + categories ---------- */
.tools {
  position: sticky; top: 64px; z-index: 30;
  background: var(--bg);
  border-bottom: 1px solid var(--line);
}
.tools-in { max-width: 1120px; margin: 0 auto; padding: 12px 16px 10px; }
.search-row { display: flex; gap: 10px; }
.search-box { position: relative; flex: 1; }
.search-box svg { position: absolute; left: 12px; top: 50%; transform: translateY(-50%); opacity: .55; }
.search-box input {
  width: 100%; height: 46px; border-radius: 12px;
  border: 1.5px solid var(--line); background: var(--surface);
  padding: 0 14px 0 40px; color: var(--ink); font-size: 16px;
}
.search-box input:focus { outline: 2px solid var(--green); outline-offset: 1px; border-color: transparent; }
.chips { display: flex; gap: 8px; overflow-x: auto; padding: 10px 2px 2px; scrollbar-width: none; }
.chips::-webkit-scrollbar { display: none; }
.chip {
  flex: none; border: 1.5px solid var(--line); background: var(--surface);
  color: var(--ink); font-weight: 700; font-size: 14px;
  padding: 9px 15px; border-radius: 999px; min-height: 40px;
}
.chip.active { background: var(--green); border-color: var(--green); color: #fff; }

/* ---------- Catalog ---------- */
main { max-width: 1120px; margin: 0 auto; padding: 8px 16px 40px; }
section.cat { margin-top: 30px; scroll-margin-top: 150px; }
.cat-head { position: relative; border-radius: var(--radius); overflow: hidden; margin-bottom: 16px; }
.cat-head img { width: 100%; height: 150px; object-fit: cover; }
.cat-head .veil {
  position: absolute; inset: 0;
  background: linear-gradient(90deg, rgba(16,34,20,.78), rgba(16,34,20,.25));
  display: flex; align-items: flex-end; padding: 16px 18px;
}
.cat-head h3 {
  font-family: "Bitter", serif; color: #fff; margin: 0;
  font-size: clamp(22px, 4.5vw, 30px); font-weight: 800;
}
.cat-head .count { color: #ffe1a8; font-weight: 700; font-size: 14px; margin-left: 10px; }
.grid {
  display: grid; gap: 12px;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
}
@media (max-width: 560px) { .grid { grid-template-columns: 1fr 1fr; gap: 10px; } }
.card {
  background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--radius); padding: 14px;
  display: flex; flex-direction: column; gap: 6px;
}
.card .photo {
  margin: -14px -14px 8px; overflow: hidden;
  border-radius: var(--radius) var(--radius) 0 0;
  aspect-ratio: 4 / 3; background: var(--surface-2);
}
.card .photo img { width: 100%; height: 100%; object-fit: cover; }
.card h4 { margin: 0; font-size: 16px; line-height: 1.25; font-weight: 700; }
.card .detail { margin: 0; color: var(--ink-soft); font-size: 13px; min-height: 17px; }
.card .price {
  margin-top: auto; font-size: 21px; font-weight: 800; color: var(--green);
  font-variant-numeric: tabular-nums;
}
.card .price small { font-size: 13px; font-weight: 700; }
.add-btn {
  margin-top: 6px; width: 100%; min-height: 44px;
  background: var(--green); color: #fff; border: 0; border-radius: 10px;
  font-weight: 800; font-size: 15px;
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
}
.add-btn:active { background: var(--green-dark); }
.stepper {
  margin-top: 6px; display: none; align-items: center; justify-content: space-between;
  background: var(--green-soft); border-radius: 10px; padding: 4px;
}
.stepper.on { display: flex; }
.stepper button {
  width: 40px; height: 40px; border-radius: 8px; border: 0;
  background: var(--surface); color: var(--ink);
  font-size: 20px; font-weight: 800; line-height: 1;
  display: inline-flex; align-items: center; justify-content: center;
}
.stepper .qty { font-weight: 800; font-size: 16px; font-variant-numeric: tabular-nums; }
.no-results {
  display: none; text-align: center; padding: 44px 16px; color: var(--ink-soft);
  font-size: 16px;
}

/* ---------- How to order ---------- */
.howto {
  margin-top: 44px; background: var(--surface); border: 1px solid var(--line);
  border-radius: var(--radius); padding: 22px 20px;
}
.howto h3 { font-family: "Bitter", serif; margin: 0 0 14px; font-size: 22px; }
.steps { display: grid; gap: 14px; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); }
.step { display: flex; gap: 12px; }
.step .n {
  flex: none; width: 34px; height: 34px; border-radius: 50%;
  background: var(--green); color: #fff; font-weight: 800;
  display: inline-flex; align-items: center; justify-content: center;
}
.step p { margin: 3px 0 0; font-size: 14.5px; line-height: 1.45; }
.step p b { display: block; font-size: 15px; }

/* ---------- Footer ---------- */
footer {
  margin-top: 48px; background: var(--green-dark); color: #eaf3e6;
}
.foot-in { max-width: 1120px; margin: 0 auto; padding: 28px 16px 34px; }
.foot-in h3 { font-family: "Bitter", serif; margin: 0 0 8px; font-size: 24px; color: #fff; }
.foot-in p { margin: 4px 0; font-size: 15px; }
.foot-in a { color: #ffd98a; font-weight: 700; text-decoration: none; }
.foot-links { display: flex; flex-wrap: wrap; gap: 10px; margin: 14px 0 20px; }
.foot-links a {
  background: rgba(255,255,255,.12); border: 1px solid rgba(255,255,255,.3);
  padding: 10px 16px; border-radius: 999px; color: #fff; min-height: 44px;
  display: inline-flex; align-items: center;
}
.credit {
  border-top: 1px solid rgba(255,255,255,.25); padding-top: 16px;
  font-size: 14px; opacity: .9; display: flex; flex-wrap: wrap; gap: 6px 18px; justify-content: space-between;
}
.credit b { color: #fff; }

/* ---------- Floating cart bar (mobile) ---------- */
.floatbar {
  position: fixed; left: 12px; right: 12px; bottom: calc(12px + env(safe-area-inset-bottom));
  z-index: 35; display: none;
}
.floatbar.show { display: block; }
.floatbar button {
  width: 100%; min-height: 54px; border: 0; border-radius: 14px;
  background: var(--green-dark); color: #fff; box-shadow: var(--shadow);
  font-size: 16px; font-weight: 800;
  display: flex; align-items: center; justify-content: space-between; padding: 0 18px;
}

/* ---------- Cart drawer ---------- */
.scrim {
  position: fixed; inset: 0; background: rgba(10, 18, 10, .55);
  z-index: 50; opacity: 0; pointer-events: none; transition: opacity .2s;
}
.scrim.open { opacity: 1; pointer-events: auto; }
.drawer {
  position: fixed; top: 0; right: 0; bottom: 0; z-index: 60;
  width: min(430px, 100vw); background: var(--bg);
  transform: translateX(105%); transition: transform .25s ease;
  display: none; flex-direction: column; box-shadow: var(--shadow);
}
.drawer.shown { display: flex; }
.drawer.enter { transform: translateX(0); }
.drawer-head {
  display: flex; align-items: center; gap: 10px;
  padding: 16px; background: var(--green-dark); color: #fff;
}
.drawer-head h3 { font-family: "Bitter", serif; margin: 0; font-size: 21px; }
.drawer-head .close {
  margin-left: auto; background: rgba(255,255,255,.15); color: #fff; border: 0;
  width: 42px; height: 42px; border-radius: 10px; font-size: 20px;
}
.drawer-body { flex: 1; overflow-y: auto; padding: 14px 16px 20px; }
.empty-cart { text-align: center; color: var(--ink-soft); padding: 40px 10px; font-size: 15.5px; }
.cart-actions {
  display: none; align-items: center; justify-content: space-between; gap: 10px;
  margin-bottom: 12px; flex-wrap: wrap;
}
.cart-actions.show { display: flex; }
.cart-actions .cart-actions-label { font-size: 14px; font-weight: 700; color: var(--ink-soft); }
.clear-cart-btn {
  display: inline-flex; align-items: center; gap: 7px;
  min-height: 42px; padding: 9px 14px; border-radius: 10px;
  border: 1.5px solid var(--red); background: transparent; color: var(--red);
  font-weight: 800; font-size: 14px;
}
.clear-cart-btn:active { transform: scale(.97); }
.clear-cart-btn.armed { background: var(--red); color: #fff; border-color: var(--red); }
@media (prefers-color-scheme: dark) {
  .clear-cart-btn { color: #ff9a7a; border-color: #e0684a; }
  .clear-cart-btn.armed { background: #c8502f; color: #fff; border-color: #c8502f; }
}
.line {
  display: grid; gap: 6px 10px; align-items: center;
  grid-template-columns: 1fr auto;
  grid-template-areas: "info remove" "step sub";
  background: var(--surface); border: 1px solid var(--line);
  border-radius: 12px; padding: 10px 12px; margin-bottom: 10px;
}
.line .info { grid-area: info; min-width: 0; }
.line .info b { display: block; font-size: 14.5px; line-height: 1.3; }
.line .info span { color: var(--ink-soft); font-size: 13px; font-variant-numeric: tabular-nums; }
.line .mini-step { grid-area: step; justify-self: start; display: flex; align-items: center; gap: 2px; }
.line .mini-step button {
  width: 36px; height: 36px; border-radius: 8px; border: 1px solid var(--line);
  background: var(--surface-2); color: var(--ink); font-size: 17px; font-weight: 800;
}
.line .mini-step .q { min-width: 26px; text-align: center; font-weight: 800; font-variant-numeric: tabular-nums; }
.line .sub { grid-area: sub; justify-self: end; font-weight: 800; min-width: 74px; text-align: right; font-variant-numeric: tabular-nums; font-size: 14.5px; }
.line .remove-btn {
  grid-area: remove; justify-self: end; align-self: start;
  display: inline-flex; align-items: center; gap: 6px;
  min-height: 38px; padding: 7px 11px; border-radius: 9px;
  border: 1px solid #eec3b2; background: #fbe9e2; color: #8c2b12;
  font-size: 13.5px; font-weight: 800; line-height: 1;
}
.line .remove-btn:active { transform: scale(.96); }
@media (prefers-color-scheme: dark) {
  .line .remove-btn { background: #43241a; color: #ffb59d; border-color: #6e3a28; }
}
.total-row {
  display: flex; justify-content: space-between; align-items: baseline;
  padding: 12px 4px 4px; font-size: 17px; font-weight: 700;
}
.total-row .grand { font-size: 24px; font-weight: 800; color: var(--green); font-variant-numeric: tabular-nums; }
.sum-row {
  display: flex; justify-content: space-between; align-items: baseline;
  padding: 5px 4px 0; font-size: 15px; color: var(--ink-soft);
}
.sum-row b { color: var(--ink); font-weight: 700; font-variant-numeric: tabular-nums; }

form.order { margin-top: 18px; border-top: 1px dashed var(--line); padding-top: 18px; }
form.order h4 { font-family: "Bitter", serif; font-size: 19px; margin: 0 0 12px; }
.field { margin-bottom: 12px; }
.field label { display: block; font-weight: 700; font-size: 14px; margin-bottom: 6px; }
.field input, .field textarea {
  width: 100%; min-height: 46px; border-radius: 10px;
  border: 1.5px solid var(--line); background: var(--surface);
  padding: 10px 12px; color: var(--ink); font-size: 16px;
}
.field textarea { min-height: 64px; resize: vertical; }
.field input:focus, .field textarea:focus { outline: 2px solid var(--green); outline-offset: 1px; border-color: transparent; }
.radio-group { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.radio-card { display: block; cursor: pointer; }
.radio-card .face {
  display: flex; align-items: center; justify-content: center; gap: 9px;
  border: 1.5px solid var(--line); background: var(--surface);
  border-radius: 10px; padding: 12px; min-height: 48px;
  font-weight: 700; font-size: 14.5px; text-align: center;
}
.radio-card input {
  width: 20px; height: 20px; margin: 0; flex: none;
  accent-color: var(--green); cursor: pointer;
}
.radio-card:has(input:checked) .face { border-color: var(--green); background: var(--green-soft); }
.radio-card input:focus-visible { outline: 2px solid var(--green); outline-offset: 2px; }
.zelle-box {
  display: none; background: var(--green-soft); border: 1px solid var(--line);
  border-radius: 10px; padding: 12px 14px; margin-top: 10px; font-size: 14.5px;
}
.zelle-box.show { display: block; }
.zelle-box .num { font-size: 18px; font-weight: 800; letter-spacing: .3px; }
.copy-btn {
  margin-left: 8px; border: 1px solid var(--green); background: transparent; color: var(--green);
  border-radius: 8px; padding: 6px 12px; font-weight: 700; min-height: 36px;
}
.form-error {
  display: none; background: #fbe9e2; color: #8c2b12; border: 1px solid #eec3b2;
  border-radius: 10px; padding: 10px 12px; font-size: 14px; font-weight: 600; margin-bottom: 12px;
}
@media (prefers-color-scheme: dark) { .form-error { background: #43241a; color: #ffb59d; border-color: #6e3a28; } }
.form-error.show { display: block; }
.send-btn {
  width: 100%; min-height: 56px; border: 0; border-radius: 12px;
  background: var(--wa); color: #fff; font-size: 17px; font-weight: 800;
  display: inline-flex; align-items: center; justify-content: center; gap: 10px;
}
.send-btn:active { background: var(--wa-dark); }
.send-note { text-align: center; color: var(--ink-soft); font-size: 13px; margin: 10px 4px 0; }
body.locked { overflow: hidden; }

body.script:
var WHATSAPP = "5352783094";
var ZELLE = "+1 (702) 460-5048";
var DELIVERY_ZONES = { "Cojímar": 200, "Bahía": 500, "Camilo": 500, "Lamar": 500 };
