/* ---------- Sonido "din" (Web Audio, sin archivos) ---------- */
var audioCtx = null;
function playTone(freq, delay, dur) {
  try {
    if (!audioCtx) {
      var AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      audioCtx = new AC();
    }
    if (audioCtx.state === "suspended") audioCtx.resume();
    var t0 = audioCtx.currentTime + (delay || 0);
    var osc = audioCtx.createOscillator();
    var gain = audioCtx.createGain();
    osc.type = "sine";
    osc.frequency.setValueAtTime(freq, t0);
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.exponentialRampToValueAtTime(0.22, t0 + 0.015);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(gain);
    gain.connect(audioCtx.destination);
    osc.start(t0);
    osc.stop(t0 + dur + 0.05);
  } catch (e) { /* sin sonido si el navegador no lo permite */ }
}
function ding() { playTone(1318.5, 0, 0.35); playTone(1760, 0.07, 0.45); }
function dingOrder() { playTone(1046.5, 0, 0.3); playTone(1318.5, 0.09, 0.3); playTone(1568, 0.18, 0.55); }

