PRODUCTS.forEach(function (pr, i) { pr.id = i; });

var cart = {}; // id -> qty

function fmt(n) {
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ".");
}
function money(n) { return fmt(n) + " CUP"; }

function normalize(s) {
  return s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

/* ---------- Render catalog ---------- */
var catalogEl = document.getElementById("catalog");
var chipsEl = document.getElementById("chips");

var allChip = document.createElement("button");
allChip.type = "button";
allChip.className = "chip active";
allChip.textContent = "Todo";
allChip.addEventListener("click", function () { selectChip(allChip, null); });
chipsEl.appendChild(allChip);

CATEGORIES.forEach(function (cat) {
  var chip = document.createElement("button");
  chip.type = "button";
  chip.className = "chip";
  chip.textContent = cat.name;
  chip.addEventListener("click", function () { selectChip(chip, cat.id); });
  chipsEl.appendChild(chip);

  var sec = document.createElement("section");
  sec.className = "cat";
  sec.id = "cat-" + cat.id;
  sec.setAttribute("data-cat", cat.id);

  var head = document.createElement("div");
  head.className = "cat-head";
  var items = PRODUCTS.filter(function (p) { return p.c === cat.id; });
  head.innerHTML = '<img src="' + cat.img + '" alt="' + cat.alt + '" loading="lazy" />' +
    '<div class="veil"><h3>' + cat.name + '<span class="count">' + items.length + ' productos</span></h3></div>';
  sec.appendChild(head);

  var grid = document.createElement("div");
  grid.className = "grid";
  items.forEach(function (p) { grid.appendChild(productCard(p)); });
  sec.appendChild(grid);
  catalogEl.appendChild(sec);
});

function productCard(p) {
  var card = document.createElement("article");
  card.className = "card";
  card.setAttribute("data-name", normalize(p.n + " " + p.d));
  card.setAttribute("data-id", p.id);
  card.innerHTML =
    (p.img ? '<div class="photo"><img src="' + p.img + '" alt="Foto de ' + p.n + '" loading="lazy" /></div>' : "") +
    "<h4>" + p.n + "</h4>" +
    '<p class="detail">' + (p.d || "&nbsp;") + "</p>" +
    '<div class="price">' + fmt(p.p) + " <small>CUP</small></div>";

  var add = document.createElement("button");
  add.type = "button";
  add.className = "add-btn";
  add.innerHTML = '<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg> Añadir';
  add.addEventListener("click", function () { changeQty(p.id, 1); });
  card.appendChild(add);

  var step = document.createElement("div");
  step.className = "stepper";
  step.setAttribute("data-stepper", p.id);
  var minus = document.createElement("button");
  minus.type = "button"; minus.textContent = "−"; minus.setAttribute("aria-label", "Quitar uno de " + p.n);
  minus.addEventListener("click", function () { changeQty(p.id, -1); });
  var qty = document.createElement("span");
  qty.className = "qty"; qty.setAttribute("data-qty", p.id); qty.textContent = "0";
  var plus = document.createElement("button");
  plus.type = "button"; plus.textContent = "+"; plus.setAttribute("aria-label", "Añadir uno más de " + p.n);
  plus.addEventListener("click", function () { changeQty(p.id, 1); });
  step.appendChild(minus); step.appendChild(qty); step.appendChild(plus);
  card.appendChild(step);
  return card;
}

function selectChip(chip, catId) {
  var chips = chipsEl.querySelectorAll(".chip");
  for (var i = 0; i < chips.length; i++) chips[i].classList.remove("active");
  chip.classList.add("active");
  if (catId) {
    var target = document.getElementById("cat-" + catId);
    if (target) target.scrollIntoView({ behavior: "smooth", block: "start" });
  } else {
    window.scrollTo({ top: 0, behavior: "smooth" });
  }
}

/* ---------- Search ---------- */
var searchInput = document.getElementById("search");
var noResults = document.getElementById("noResults");
searchInput.addEventListener("input", function () {
  var q = normalize(searchInput.value.trim());
  var anyVisible = false;
  var sections = catalogEl.querySelectorAll("section.cat");
  sections.forEach(function (sec) {
    var visible = 0;
    sec.querySelectorAll(".card").forEach(function (card) {
      var show = !q || card.getAttribute("data-name").indexOf(q) !== -1;
      card.style.display = show ? "" : "none";
      if (show) visible++;
    });
    sec.style.display = visible ? "" : "none";
    if (visible) anyVisible = true;
  });
  noResults.style.display = anyVisible ? "none" : "block";
});

/* ---------- Cart logic ---------- */
var cartCountEl = document.getElementById("cartCount");
var cartLinesEl = document.getElementById("cartLines");
var totalsBox = document.getElementById("totalsBox");
var subTotalEl = document.getElementById("subTotal");
var deliveryRow = document.getElementById("deliveryRow");
var deliveryLabel = document.getElementById("deliveryLabel");
var deliveryFeeEl = document.getElementById("deliveryFee");
var zelleRow = document.getElementById("zelleRow");
var zelleFeeEl = document.getElementById("zelleFee");
var grandTotalEl = document.getElementById("grandTotal");
var floatbar = document.getElementById("floatbar");
var floatLabel = document.getElementById("floatLabel");
var floatTotal = document.getElementById("floatTotal");
var cartActionsEl = document.getElementById("cartActions");
var cartActionsLabel = document.getElementById("cartActionsLabel");
var clearCartBtn = document.getElementById("clearCartBtn");
var clearCartLabel = document.getElementById("clearCartLabel");
var clearArmed = false;
var clearTimer = null;
function disarmClear() {
  clearArmed = false;
  if (clearTimer) { clearTimeout(clearTimer); clearTimer = null; }
  clearCartBtn.classList.remove("armed");
  clearCartLabel.textContent = "Vaciar carrito";
}
function removeItem(id) {
  delete cart[id];
  disarmClear();
  renderCart();
}
function clearCart() {
  cart = {};
  disarmClear();
  renderCart();
}
clearCartBtn.addEventListener("click", function () {
  if (!Object.keys(cart).length) return;
  if (!clearArmed) {
    clearArmed = true;
    clearCartBtn.classList.add("armed");
    clearCartLabel.textContent = "¿Seguro? Toca otra vez";
    clearTimer = setTimeout(disarmClear, 3500);
    return;
  }
  clearCart();
});

function cartTotals() {
  var count = 0, total = 0;
  Object.keys(cart).forEach(function (id) {
    count += cart[id];
    total += cart[id] * PRODUCTS[id].p;
  });
  return { count: count, total: total };
}

/* Extras del pedido según el formulario: entrega por zona y comisión Zelle */
function orderExtras() {
  var dSel = form.querySelector('input[name="delivery"]:checked');
  var isDelivery = !!(dSel && dSel.value === "Entrega a domicilio");
  var zSel = form.querySelector('input[name="zone"]:checked');
  var zone = isDelivery && zSel ? zSel.value : null;
  var pSel = form.querySelector('input[name="payment"]:checked');
  var isZelle = !!(pSel && pSel.value === "Zelle");
  return { isDelivery: isDelivery, zone: zone, isZelle: isZelle };
}
function grandTotal(subtotal) {
  var ex = orderExtras();
  var deliveryFee = ex.zone ? (DELIVERY_ZONES[ex.zone] || 0) : 0;
  var base = subtotal + deliveryFee;
  var zelleFee = ex.isZelle ? Math.round(base * ZELLE_FEE) : 0;
  return {
    isDelivery: ex.isDelivery, zone: ex.zone, isZelle: ex.isZelle,
    deliveryFee: deliveryFee, zelleFee: zelleFee, total: base + zelleFee
  };
}

function changeQty(id, delta) {
  var q = (cart[id] || 0) + delta;
  if (q <= 0) delete cart[id]; else cart[id] = q;
  if (delta > 0) ding();
  renderCart();
}
function setQty(id, q) {
  if (q <= 0) delete cart[id]; else cart[id] = q;
  renderCart();
}

function renderCart() {
  var t = cartTotals();
  cartCountEl.textContent = t.count;

  // Card steppers
  PRODUCTS.forEach(function (p) {
    var step = document.querySelector('[data-stepper="' + p.id + '"]');
    if (!step) return;
    var q = cart[p.id] || 0;
    step.classList.toggle("on", q > 0);
    step.parentElement.querySelector(".add-btn").style.display = q > 0 ? "none" : "";
    step.querySelector('[data-qty="' + p.id + '"]').textContent = q;
  });

  // Drawer lines
  cartLinesEl.innerHTML = "";
  var ids = Object.keys(cart);
  if (!ids.length) {
    disarmClear();
    cartActionsEl.classList.remove("show");
    cartLinesEl.innerHTML = '<p class="empty-cart">Tu carrito está vacío.<br />Vuelve al catálogo y toca «Añadir» en los productos que quieras.</p>';
    totalsBox.style.display = "none";
  } else {
    cartActionsEl.classList.add("show");
    cartActionsLabel.textContent = t.count + (t.count === 1 ? " producto" : " productos") + " en el carrito";
    if (!clearArmed) clearCartLabel.textContent = "Vaciar carrito";
    ids.forEach(function (id) {
      var p = PRODUCTS[id];
      var line = document.createElement("div");
      line.className = "line";
      var info = document.createElement("div");
      info.className = "info";
      info.innerHTML = "<b>" + p.n + "</b><span>" + money(p.p) + (p.d ? " · " + p.d : "") + "</span>";
      var mini = document.createElement("div");
      mini.className = "mini-step";
      var bMinus = document.createElement("button");
      bMinus.type = "button"; bMinus.textContent = "−"; bMinus.setAttribute("aria-label", "Quitar uno");
      bMinus.addEventListener("click", function () { changeQty(p.id, -1); });
      var qSpan = document.createElement("span");
      qSpan.className = "q"; qSpan.textContent = cart[id];
      var bPlus = document.createElement("button");
      bPlus.type = "button"; bPlus.textContent = "+"; bPlus.setAttribute("aria-label", "Añadir uno");
      bPlus.addEventListener("click", function () { changeQty(p.id, 1); });
      mini.appendChild(bMinus); mini.appendChild(qSpan); mini.appendChild(bPlus);
      var sub = document.createElement("div");
      sub.className = "sub"; sub.textContent = money(p.p * cart[id]);
      var removeBtn = document.createElement("button");
      removeBtn.type = "button";
      removeBtn.className = "remove-btn";
      removeBtn.setAttribute("aria-label", "Eliminar " + p.n + " del carrito");
      removeBtn.innerHTML = '<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 6h18"/><path d="M8 6V4a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg> Quitar';
      removeBtn.addEventListener("click", function () { removeItem(p.id); });
      line.appendChild(info); line.appendChild(removeBtn); line.appendChild(mini); line.appendChild(sub);
      cartLinesEl.appendChild(line);
    });
    var g = grandTotal(t.total);
    totalsBox.style.display = "";
    subTotalEl.textContent = money(t.total);
    if (g.isDelivery) {
      deliveryRow.style.display = "";
      if (g.zone) {
        deliveryLabel.textContent = "Entrega a domicilio (" + g.zone + ")";
        deliveryFeeEl.textContent = money(g.deliveryFee);
      } else {
        deliveryLabel.textContent = "Entrega a domicilio";
        deliveryFeeEl.textContent = "según la zona";
      }
    } else {
      deliveryRow.style.display = "none";
    }
    if (g.isZelle) {
      zelleRow.style.display = "";
      zelleFeeEl.textContent = money(g.zelleFee);
    } else {
      zelleRow.style.display = "none";
    }
    grandTotalEl.textContent = money(g.total);
  }

  // Floating bar
  if (t.count > 0 && !drawer.classList.contains("shown")) {
    floatbar.classList.add("show");
    floatLabel.textContent = "Ver carrito · " + t.count + (t.count === 1 ? " producto" : " productos");
    floatTotal.textContent = money(grandTotal(t.total).total);
  } else {
    floatbar.classList.remove("show");
  }
}

/* ---------- Drawer ---------- */
var drawer = document.getElementById("drawer");
var scrim = document.getElementById("scrim");
var closeTimer = null;
function openCart() {
  if (closeTimer) { clearTimeout(closeTimer); closeTimer = null; }
  drawer.classList.add("shown");
  // Force reflow so the slide-in transition runs from off-canvas.
  void drawer.offsetWidth;
  drawer.classList.add("enter");
  scrim.classList.add("open");
  document.body.classList.add("locked");
  floatbar.classList.remove("show");
}
function closeCart() {
  drawer.classList.remove("enter");
  scrim.classList.remove("open");
  document.body.classList.remove("locked");
  closeTimer = setTimeout(function () {
    drawer.classList.remove("shown");
    closeTimer = null;
  }, 260);
  renderCart();
}
document.getElementById("openCart").addEventListener("click", openCart);
document.getElementById("floatOpen").addEventListener("click", openCart);
document.getElementById("closeCart").addEventListener("click", closeCart);
scrim.addEventListener("click", closeCart);

/* ---------- Order form ---------- */
var form = document.getElementById("orderForm");
var addressField = document.getElementById("addressField");
var zelleBox = document.getElementById("zelleBox");
var formError = document.getElementById("formError");

form.addEventListener("change", function (e) {
  if (e.target.name === "delivery") {
    addressField.style.display = e.target.value === "Entrega a domicilio" ? "" : "none";
  }
  if (e.target.name === "payment") {
    zelleBox.classList.toggle("show", e.target.value === "Zelle");
  }
  renderCart();
});

document.getElementById("copyZelle").addEventListener("click", function () {
  var btn = this;
  function done() { btn.textContent = "¡Copiado!"; setTimeout(function () { btn.textContent = "Copiar"; }, 1800); }
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText("+17024605048").then(done, done);
  } else { done(); }
});

function showError(msg) {
  formError.textContent = msg;
  formError.classList.add("show");
  formError.scrollIntoView({ behavior: "smooth", block: "center" });
}

form.addEventListener("submit", function (e) {
  e.preventDefault();
  formError.classList.remove("show");
  var t = cartTotals();
  var name = document.getElementById("fName").value.trim();
  var phone = document.getElementById("fPhone").value.trim();
  var delivery = form.querySelector('input[name="delivery"]:checked').value;
  var zoneSel = form.querySelector('input[name="zone"]:checked');
  var zone = zoneSel ? zoneSel.value : "";
  var address = document.getElementById("fAddress").value.trim();
  var payment = form.querySelector('input[name="payment"]:checked').value;
  var note = document.getElementById("fNote").value.trim();

  if (!t.count) { showError("Tu carrito está vacío. Añade al menos un producto antes de enviar el pedido."); return; }
  if (!name) { showError("Escribe tu nombre para que la tienda sepa quién hace el pedido."); return; }
  if (!phone) { showError("Escribe tu teléfono para que la tienda pueda contactarte."); return; }
  if (delivery === "Entrega a domicilio" && !zone) { showError("Elige tu zona de entrega: Cojímar (200 CUP), Bahía (500 CUP), Camilo (500 CUP) o Lamar (500 CUP)."); return; }
  if (delivery === "Entrega a domicilio" && !address) { showError("Escribe la dirección de entrega."); return; }

  var g = grandTotal(t.total);
  var lines = [];
  lines.push("*Nuevo pedido — Doña Loly*");
  lines.push("");
  lines.push("*Nombre:* " + name);
  lines.push("*Teléfono:* " + phone);
  lines.push("*Entrega:* " + delivery + (delivery === "Entrega a domicilio" ? " — " + zone : ""));
  if (delivery === "Entrega a domicilio") lines.push("*Dirección:* " + address);
  lines.push("*Pago:* " + payment + (payment === "Zelle" ? " (al " + ZELLE + ", con 5% de comisión)" : " al recibir"));
  lines.push("");
  lines.push("*Pedido:*");
  Object.keys(cart).forEach(function (id) {
    var p = PRODUCTS[id];
    lines.push("• " + cart[id] + " × " + p.n + (p.d ? " (" + p.d + ")" : "") + " — " + money(p.p * cart[id]));
  });
  lines.push("");
  lines.push("Subtotal: " + money(t.total));
  if (g.isDelivery) lines.push("Entrega a domicilio (" + g.zone + "): " + money(g.deliveryFee));
  if (g.isZelle) lines.push("Comisión Zelle (5%): " + money(g.zelleFee));
  lines.push("*Total: " + money(g.total) + "*");
  if (note) { lines.push(""); lines.push("*Nota:* " + note); }

  dingOrder();
  var url = "https://wa.me/" + WHATSAPP + "?text=" + encodeURIComponent(lines.join("\n"));
  window.open(url, "_blank");
});

renderCart();
